from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=2)
def compare(x_i, x_i_plus_1):
    if x_i > x_i_plus_1:
        return x_i_plus_1, x_i
    return x_i, x_i_plus_1

@task(returns=1)
def map(non_zero_elements, zeros, i):
    return non_zero_elements[i - zeros]


def main(x):
    n = len(x)

    non_zero_elements = [elem for elem in x if elem != 0]
    n2 = len(non_zero_elements)

    for phase in range(n2):
        if phase % 2 == 0:
            indices = range(0, n2-1, 2)
        else:
            indices = range(1, n2-1, 2)

        for i in indices:
            non_zero_elements[i], non_zero_elements[i + 1] = compare(non_zero_elements[i], non_zero_elements[i + 1])


    non_zero_elements = compss_wait_on(non_zero_elements)
    zeros = 0
    for i in range(n):
        if x[i] != 0:
            x[i] = map(non_zero_elements, zeros, i)
        else:
            zeros += 1

    x = compss_wait_on(x)
    return x
